data.model_lifecycle.py:
"""Application model lifecycle; deliberately does not flush driver/OS caches."""

import gc
import threading
import time


class ModelRuntime:
    def __init__(self, factory, fixture):
        self.factory=factory
        self.fixture=fixture
        self.infer=None
        self.generation=0
        self.lock=threading.Lock()

    def health(self):
        with self.lock:
            return {'model_ready':self.infer is not None,'generation':self.generation}

    def evict(self):
        started=time.perf_counter()
        with self.lock:
            self.infer=None
            gc.collect()
            return {'model_ready':False,'generation':self.generation,
                    'eviction_ms':(time.perf_counter()-started)*1000}

    def run(self,tensor):
        import numpy as np
        with self.lock:
            cold=self.infer is None
            preparation_ms=0.0
            details={}
            if cold:
                started=time.perf_counter()
                infer,details=self.factory()
                warmed=time.perf_counter()
                for _ in range(2):
                    scores,_=infer(self.fixture)
                    assert np.isfinite(scores).all()
                    assert np.argsort(scores)[-5:][::-1].tolist()==[258,259,157,279,152]
                self.infer=infer
                self.generation+=1
                details['warmup_ms']=(time.perf_counter()-warmed)*1000
                preparation_ms=(time.perf_counter()-started)*1000
            scores,device=self.infer(tensor)
            return scores,{**device,'was_cold':cold,'generation':self.generation,
                           'preparation_ms':preparation_ms,'preparation_details':details}


def factory_for(backend,model_path,options):
    if backend=='cpu':
        import onnxruntime as ort
        def factory():
            started=time.perf_counter()
            session=ort.InferenceSession(str(model_path),options,providers=['CPUExecutionProvider'])
            name=session.get_inputs()[0].name
            def infer(tensor):
                return session.run(None,{name:tensor})[0].reshape(-1),{'execution_device':'CPU'}
            return infer,{'session_load_ms':(time.perf_counter()-started)*1000}
        return factory
    assert backend=='intel_npu','Dynamic pilot supports CPU and Intel NPU only'
    import openvino as ov
    core=ov.Core()
    core.set_property({'CACHE_DIR':''})
    def factory():
        started=time.perf_counter()
        model=core.read_model(str(model_path))
        read_ms=(time.perf_counter()-started)*1000
        started=time.perf_counter()
        compiled=core.compile_model(model,'NPU',{'PERFORMANCE_HINT':'LATENCY'})
        compile_ms=(time.perf_counter()-started)*1000
        devices=compiled.get_property('EXECUTION_DEVICES')
        if isinstance(devices,str):devices=[devices]
        assert devices and all(d=='NPU' or d.startswith('NPU.') for d in devices)
        started=time.perf_counter()
        request=compiled.create_infer_request()
        request_ms=(time.perf_counter()-started)*1000
        def infer(tensor):
            request.infer({compiled.input(0):tensor})
            return request.get_output_tensor(0).data.reshape(-1).copy(),{'execution_devices':list(devices)}
        return infer,{'read_ms':read_ms,'compile_ms':compile_ms,'create_request_ms':request_ms}
    return factory

data.policy_runner.py:
"""Policy-independent observation and execution of the existing three-task HTTP DAG."""

import hashlib
import http.client
import json
import math
import socket
import time
from types import MappingProxyType
from urllib.parse import urlparse


def readonly(value):
    if isinstance(value,dict):
        return MappingProxyType({k:readonly(v) for k,v in value.items()})
    if isinstance(value,list):
        return tuple(readonly(v) for v in value)
    return value


class PolicyRunner:
    """Use one runner per serial client; connections are reused until close()."""

    def __init__(self,peers):
        self.peers={a:{k:p[k] for k in ['node','backend','url']} for a,p in peers.items()}
        self.connections={}

    def __enter__(self):
        return self

    def __exit__(self,*_):
        self.close()

    def close(self):
        for connection in self.connections.values():
            connection.close()
        self.connections.clear()

    def _request(self,alias,method,path,body=None,headers=None):
        try:
            if alias not in self.connections:
                url=urlparse(self.peers[alias]['url'])
                if url.scheme!='http' or not url.hostname:
                    raise ValueError('Expected an explicit HTTP worker URL')
                self.connections[alias]=http.client.HTTPConnection(url.hostname,url.port,timeout=15)
            connection=self.connections[alias]
            if connection.sock is None:
                connection.connect()
                connection.sock.setsockopt(socket.IPPROTO_TCP,socket.TCP_NODELAY,1)
            connection.request(method,path,body,headers or {})
            response=connection.getresponse()
            size=int(response.getheader('Content-Length','-1'))
            if response.status!=200 or not 0<=size<65536:
                raise ValueError(f'Invalid worker response: HTTP {response.status}, bytes {size}')
            data=response.read(size)
            if len(data)!=size or response.getheader('X-Worker-Alias')!=alias:
                raise ValueError('Worker response length or alias mismatch')
            return json.loads(data)
        except Exception:
            connection=self.connections.pop(alias,None)
            if connection is not None:
                connection.close()
            raise

    def _health(self,alias,model_sha256):
        health=self._request(alias,'GET','/healthz')
        peer=self.peers[alias]
        if (health.get('node')!=peer['node'] or health.get('backend')!=peer['backend'] or
                health.get('model_sha256')!=model_sha256 or
                type(health.get('model_ready')) is not bool or
                type(health.get('generation')) is not int):
            raise ValueError(f'Worker identity/model/lifecycle mismatch: {alias}')
        return {'node':health['node'],'backend':health['backend'],
                'service_object_ready':health['model_ready'],'service_generation':health['generation'],
                'weight_memory_resident':'unknown','received_monotonic_ns':time.monotonic_ns()}

    def _profile(self,profile,input_id,source):
        keys={'id','provenance','input_id','source','model_sha256','candidates','cost_ms'}
        if set(profile)!=keys:
            raise ValueError('Profile fields must match the common observation contract')
        detached=json.loads(json.dumps(profile,allow_nan=False))
        if (detached['input_id']!=input_id or detached['source']!=source or source not in self.peers or
                not all(isinstance(detached[k],str) and detached[k] for k in ['id','provenance','model_sha256'])):
            raise ValueError('Profile input/source/provenance does not match this request')
        candidates=detached['candidates']
        if (not isinstance(candidates,list) or len(candidates)!=3 or
                any(not isinstance(group,list) or not group or
                    any(a not in self.peers for a in group) for group in candidates)):
            raise ValueError('Expected nonempty common candidates for all three tasks')
        costs=detached['cost_ms']
        if set(costs)!={'task','ingress','edges','service_prepare'} or len(costs['edges'])!=2:
            raise ValueError('Unexpected fields in common cost profile')
        task_keys={f'{i}|{a}' for i in range(3) for a in self.peers}
        edge_keys={f'{a}|{b}' for a in self.peers for b in self.peers}
        groups=[(costs['task'],task_keys),(costs['ingress'],set(self.peers)),
                (costs['service_prepare'],set(self.peers)),
                *[(edge,edge_keys) for edge in costs['edges']]]
        for group,expected in groups:
            if set(group)!=expected:
                raise ValueError('Cost profile is missing candidates or contains unknown fields')
            if any(v is not None and (type(v) not in [int,float] or not math.isfinite(v) or v<0)
                   for v in group.values()):
                raise ValueError('Costs must be nonnegative milliseconds or null for unknown')
        return detached

    def run(self,*,request_id,input_id,body,source,profile,policy_name,policy):
        """Return a JSON-safe attempt, retaining errors as well as successful receipts."""
        started=time.perf_counter();phase_started=started;phase='validation'
        record={'request_id':request_id,'input_id':input_id,'policy':policy_name,
                'status':'error','timings_ms':{}}

        def advance(next_phase):
            nonlocal phase,phase_started
            now=time.perf_counter()
            record['timings_ms'][phase]=(now-phase_started)*1000
            phase=next_phase;phase_started=now

        try:
            frozen_profile=self._profile(profile,input_id,source)
            advance('observation')
            workers={a:self._health(a,frozen_profile['model_sha256']) for a in sorted(self.peers)}
            snapshot={'schema_version':1,'request':{'request_id':request_id,'input_id':input_id,
                      'source':source,'bytes':len(body),'sha256':hashlib.sha256(body).hexdigest()},
                      'profile':frozen_profile,'workers':workers}
            snapshot_id=hashlib.sha256(json.dumps(snapshot,sort_keys=True,allow_nan=False).encode()).hexdigest()
            snapshot['snapshot_id']=snapshot_id
            record.update(snapshot_id=snapshot_id,snapshot=snapshot)
            policy_input=readonly(snapshot)
            advance('decision')
            proposed=policy(policy_input)
            advance('plan_validation')
            if not isinstance(proposed,(list,tuple)) or any(type(a) is not str for a in proposed):
                raise ValueError('Policy must return a list or tuple of worker alias strings')
            plan=list(proposed);record['plan']=plan
            if len(plan)!=3 or any(a not in frozen_profile['candidates'][i] for i,a in enumerate(plan)):
                raise ValueError('Policy plan contains a task candidate outside the common feasible set')
            advance('state_validation')
            selected=plan[1]
            preflight=self._health(selected,frozen_profile['model_sha256'])
            record['preflight']={'alias':selected,**preflight}
            if any(preflight[k]!=workers[selected][k]
                   for k in ['service_object_ready','service_generation']):
                raise ValueError('Selected inference service state changed after observation')
            advance('workflow')
            result=self._request(plan[0],'POST','/stage/0',body,{
                'X-Plan':json.dumps(plan),'X-Request-ID':request_id,'X-Input-ID':input_id,
                'X-Payload-SHA256':snapshot['request']['sha256']})
            record['result']=result
            advance('receipt_validation')
            trace=result['trace']
            if (result['request_id']!=request_id or result.get('input_id','dog')!=input_id or
                    result['plan']!=plan or [t['stage'] for t in trace]!=[0,1,2] or
                    [t['alias'] for t in trace]!=plan or
                    [t['node'] for t in trace]!=[self.peers[a]['node'] for a in plan] or
                    [t['worker_backend'] for t in trace]!=[self.peers[a]['backend'] for a in plan] or
                    trace[0]['input_bytes']!=len(body) or
                    trace[0]['output_bytes']!=trace[1]['input_bytes'] or
                    trace[1]['output_bytes']!=trace[2]['input_bytes'] or
                    trace[0]['input_sha256']!=snapshot['request']['sha256'] or
                    trace[0]['output_sha256']!=trace[1]['input_sha256'] or
                    trace[1]['output_sha256']!=trace[2]['input_sha256']):
                raise ValueError('Workflow receipt identity or payload linkage mismatch')
            record['status']='ok'
        except Exception as error:
            record['error']={'phase':phase,'type':type(error).__name__,'message':str(error)}
        finally:
            finished=time.perf_counter()
            record['timings_ms'][phase]=(finished-phase_started)*1000
            record['total_ms']=(finished-started)*1000
        return record

data.measured_policy_bridge.py:
"""Preserve the frozen E2 calibration and policies at the common HTTP boundary."""

import hashlib
import json
from pathlib import Path

import dynamic_client
import probe
from policy_runner import readonly


def load_e2_contract(directory):
    directory=Path(directory)
    selection_bytes=(directory/'selection.json').read_bytes()
    selection=json.loads(selection_bytes)
    run=json.loads((directory/'run.json').read_text())
    workers=json.loads((directory/'workers.json').read_text())['items']
    cm=next(item for item in workers if item['kind']=='ConfigMap')['data']
    for module in [dynamic_client,probe]:
        name=Path(module.__file__).name
        digest=hashlib.sha256(Path(module.__file__).read_bytes()).hexdigest()
        if digest!=run['source_sha256'][name] or hashlib.sha256(cm[name].encode()).hexdigest()!=digest:
            raise ValueError(f'E2 source contract changed: {name}')
    for filename,digest in selection['calibration_log_sha256'].items():
        if Path(filename).name!=filename or hashlib.sha256((directory/filename).read_bytes()).hexdigest()!=digest:
            raise ValueError(f'E2 calibration evidence changed: {filename}')
    if run['design']['horizon_requests']!=4 or set(selection['profiles'])!={'arm','intel_npu'}:
        raise ValueError('This bridge preserves the two-worker E2 H4 contract only')
    digest=hashlib.sha256(selection_bytes).hexdigest()
    profiles={}
    for source,costs in selection['profiles'].items():
        profiles[source]={'id':f"e2-{run['run_id']}-{source}-{digest}",
            'provenance':f"Historical E2 dog calibration; selection SHA256 {digest}; service-object preparation H4 policy",
            'input_id':'dog','source':source,'model_sha256':probe.MODEL_SHA256,
            'candidates':[['arm','intel_npu'] for _ in range(3)],
            'cost_ms':{**costs,'service_prepare':{'arm':None,'intel_npu':selection['preparation_ms']}}}
    return {'version':1,'run_id':run['run_id'],'selection_sha256':digest,
            'model_sha256':probe.MODEL_SHA256,'profiles':profiles,
            'initial_plan':selection['initial_plan'],'preparation_ms':selection['preparation_ms'],
            'source_sha256':{name:run['source_sha256'][name] for name in ['dynamic_client.py','probe.py']},
            'calibration_log_sha256':selection['calibration_log_sha256'],
            'historical_targets':{a:{k:t[k] for k in ['node','backend']} for a,t in run['targets'].items()}}


class E2Policy:
    """One stateful instance per trajectory; abort the trajectory after a failed attempt."""

    def __init__(self,name,contract):
        if name not in ['fixed','warm_dag','ready_dag','ready_greedy','credit_hysteresis']:
            raise ValueError('Unknown E2 policy')
        self.name=name
        self.profiles=readonly(contract['profiles'])
        self.selection={'initial_plan':list(contract['initial_plan']),
                        'preparation_ms':contract['preparation_ms']}
        self.state={}
        self.information={}

    def __call__(self,snapshot):
        source=snapshot['request']['source']
        if snapshot['profile']!=self.profiles[source]:
            raise ValueError('E2 policy requires its unchanged calibrated profile and common candidates')
        costs=snapshot['profile']['cost_ms']
        plan,self.state,self.information=dynamic_client.choose(
            self.name,costs,self.selection,snapshot['workers']['intel_npu']['service_object_ready'],self.state,source)
        return list(plan)


def task_fastest(snapshot):
    """Task-only minimum among the supplied common candidates; lexical ties."""
    profile=snapshot['profile']
    if any(profile['cost_ms']['task'][f'{i}|{a}'] is None
           for i,aliases in enumerate(profile['candidates']) for a in aliases):
        raise ValueError('Task-fastest requires measured task costs for every common candidate')
    return [min(aliases,key=lambda a:(profile['cost_ms']['task'][f'{i}|{a}'],a))
            for i,aliases in enumerate(profile['candidates'])]

data.fresh_placement.py:
"""Warm static three-task baselines; no published scheduler reproduction."""

import itertools
from collections import defaultdict
import statistics

from measured_policy_bridge import task_fastest
from probe import MODEL_SHA256


def plan_cost(profile,plan):
    costs=profile['cost_ms']
    values=[costs['ingress'][plan[0]],*[costs['task'][f'{i}|{a}'] for i,a in enumerate(plan)],
            *[costs['edges'][i][f'{plan[i]}|{plan[i+1]}'] for i in range(2)]]
    if any(value is None for value in values):
        raise ValueError('Warm placement requires measured costs')
    return sum(values)


def data_greedy(snapshot):
    profile=snapshot['profile'];costs=profile['cost_ms'];candidates=profile['candidates']
    plan=[min(candidates[0],key=lambda a:(costs['ingress'][a]+costs['task'][f'0|{a}'],a))]
    for i in [1,2]:
        plan.append(min(candidates[i],key=lambda a:(costs['edges'][i-1][f'{plan[-1]}|{a}']+
                                                   costs['task'][f'{i}|{a}'],a)))
    return plan


def dag_enumeration(snapshot):
    profile=snapshot['profile']
    return list(min(itertools.product(*profile['candidates']),key=lambda p:(plan_cost(profile,p),p)))


POLICIES={'task_fastest':task_fastest,'data_greedy':data_greedy,'dag_enumeration':dag_enumeration}


def freeze_profiles(rows,corpus,aliases,evidence_id):
    """Use calibration rows only; preserve every mismatch in the eligibility counts."""
    aliases=sorted(aliases)
    quality={key:{a:{'observations':0,'matches':0,'eligible':False} for a in aliases} for key in corpus}
    for row in rows:
        if row['status']!='ok':
            raise ValueError('Cannot freeze an incomplete HTTP calibration')
        entry=quality[row['input_id']][row['plan'][1]]
        entry['observations']+=1
        entry['matches']+=int(row['result']['top5']==corpus[row['input_id']]['reference_top5'])
    for key,devices in quality.items():
        for entry in devices.values():
            entry['eligible']=entry['observations']>0 and entry['matches']==entry['observations']
        if not any(e['eligible'] for e in devices.values()):
            raise ValueError(f'No inference candidate satisfies the quality contract: {key}')
    measured=[row for row in rows if not row['warmup']]
    sources=sorted({r['source'] for r in measured})
    profiles={}
    for source,key in itertools.product(sources,corpus):
        group=[r for r in measured if r['source']==source and r['input_id']==key]
        if {tuple(r['plan']) for r in group}!=set(itertools.product(aliases,repeat=3)):
            raise ValueError('Every input/source requires all three-task calibration placements')
        tasks=defaultdict(list);ingress=defaultdict(list);edges=[defaultdict(list),defaultdict(list)]
        for row in group:
            trace=row['result']['trace'];plan=row['plan']
            if trace[1]['device'].get('was_cold',False):
                raise ValueError('Warm calibration unexpectedly prepared a cold model')
            for i,entry in enumerate(trace):tasks[f'{i}|{plan[i]}'].append(entry['task_ms'])
            ingress[plan[0]].append(row['timings_ms']['workflow']-trace[0]['task_ms']-trace[0]['rpc_next_ms'])
            edges[0][f'{plan[0]}|{plan[1]}'].append(trace[0]['rpc_next_ms']-trace[1]['task_ms']-trace[1]['rpc_next_ms'])
            edges[1][f'{plan[1]}|{plan[2]}'].append(trace[1]['rpc_next_ms']-trace[2]['task_ms'])
        median=lambda values:{k:statistics.median(v) for k,v in values.items()}
        costs={'task':median(tasks),'ingress':median(ingress),'edges':[median(e) for e in edges],
               'service_prepare':{a:None for a in aliases}}
        if any(v<0 for values in [costs['task'],costs['ingress'],*costs['edges']] for v in values.values()):
            raise ValueError('Negative observed RPC residual; preserve and investigate calibration')
        candidates=[list(aliases),[a for a in aliases if quality[key][a]['eligible']],list(aliases)]
        profiles[source+'|'+key]={'id':evidence_id+'|'+source+'|'+key,
            'provenance':'Fresh warm-only calibration '+evidence_id+'; CPU-reference exact Top5 order gate',
            'input_id':key,'source':source,'model_sha256':MODEL_SHA256,'candidates':candidates,'cost_ms':costs}
    return profiles,quality
